// go: github.com/microsoft/TypeScript/tsc/internal/transformers/estransforms.GetESTransformer 5d5360ac
fun getESTransformer(opts: TransformOptions?): Transformer? {
    val options: CompilerOptions? = opts!!.compilerOptions
    when (options.getEmitScriptTarget().value) {
        99 -> {
            return esDecoratorAndClassFields!!(opts)
        }
        13, 12, 11, 10, 9, 8 -> {
            return newESNextTransformer!!(opts)
        }
        7 -> {
            return newES2021Transformer!!(opts)
        }
        6 -> {
            return newES2020Transformer!!(opts)
        }
        5 -> {
            return newES2019Transformer!!(opts)
        }
        4 -> {
            return newES2018Transformer!!(opts)
        }
        3 -> {
            return newES2017Transformer!!(opts)
        }
        else -> {
            return newES2016Transformer!!(opts)
        }
    }
    goUnreachable()
}

